const { EOL } = require('os');

function findGreeting(str) {
  const word = 'hello';
  let i = 0;
  for(const l of str) {
    if(l == word[i]) {
      i++;
    }
  }
  return i == word.length ? 'YES' : 'NO';
}

let data = '';
process.stdin.on('data', c => data += c);
process.stdin.on('end', () => {
  const res = findGreeting(data.split(EOL)[0]);
  console.log(res);
});
